	/**  Quantos itens o Prism vai listar como "não confiáveis". */
	untrusted: number,
	/**  Há mods da CurseForge e falta a chave para conferir a distribuição. */
	curseforgeKeyMissing: boolean,
	/**  Mods que o Prism não conseguiria baixar. */
