	/**  A mensagem, sem o prefixo do log. */
	message: string,
	/**  A linha original do log. */
	logLine: string,
	/**
	 *  O log de onde veio, relativo à pasta do jogo (`logs/kubejs/server.log`), ou `null` quando
	 *  veio ao vivo do servidor web do KubeJS.
	 */
	logFile: string | null,
